fulfill.run:
const re = $self.address.entire
const STORAGE_KEY = 'devtool_cors'
$self.state = $observable({ enabled: false, list: [] })
$self.buildSummary = (d) => {
  const p = []
  if (d.excludeDomains && d.excludeDomains.length > 0) p.push('排除: ' + d.excludeDomains.join(', '))
  if (d.urlFilter) p.push((d.urlFilterIsRegex ? '正则' : 'URL') + ': ' + d.urlFilter)
  if (d.methods && d.methods.length > 0) p.push('方法: ' + d.methods.join('/'))
  if (d.resourceTypes && d.resourceTypes.length > 0) p.push('类型: ' + d.resourceTypes.join('/'))
  if (d.domainType) p.push(d.domainType === 'firstParty' ? '第一方' : '第三方')
  return p.length > 0 ? p.join('  ') : '—'
}
$self.loadCors = async () => {
  try {
    const res = await $chrome.storage.local.get(STORAGE_KEY)
    const state = res[STORAGE_KEY] || { enabled: false, domains: [] }
    const list = (state.domains || []).map((d) => ({ ...d, matchScope: d.matchScope || 'request', conditionSummary: $self.buildSummary(d) }))
    $self.state.enabled = state.enabled
    $self.state.list = list
  } catch (e) {
    $logger.error('加载跨域配置失败', e)
    $message.error('加载跨域配置失败')
  }
}
$self.saveCors = async (enabled, displayList) => {
  const clean = JSON.parse(JSON.stringify(displayList || [])).map((d) => { const c = {}; Object.keys(d).forEach((k) => { if (k !== 'conditionSummary') c[k] = d[k] }); return c })
  await $chrome.storage.local.set({ [STORAGE_KEY]: { enabled, domains: clean } })
}
$self.showAddOrUpdateDialog = (row) => {
  const dialog = $self.query(re + '.editDialog').take()
  if (dialog) {
    dialog.value = row ? { ...row } : { matchScope: 'request', urlFilterIsRegex: false, domainType: '' }
    dialog.setComponentProps({ open: true, title: row ? '编辑规则' : '新增规则' })
  }
}
$effect(() => { $self.loadCors() }, [])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('corsSettingsDiv') + 'corsSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => { $self.value = rf.state.enabled }, [rf.state.enabled])
$props({
  onChange: (checked) => {
    rf.state.enabled = checked
    rf.saveCors(checked, rf.state.list).then(() => $message.success(checked ? '跨域放宽已开启' : '跨域放宽已关闭'))
  },
})

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('corsSettingsDiv') + 'corsSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const en = rf.state.enabled
  $self.value = en ? '' : '关闭后不会生成任何放宽 CORS 的规则'
  $self.display = en ? 'none' : 'visible'
}, [rf.state.enabled])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('corsSettingsDiv') + 'corsSettingsDiv'.length)
const rf = $self.query(re).take()
$props({ onClick: () => rf.showAddOrUpdateDialog(null) })

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('corsSettingsDiv') + 'corsSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  $self.value = row ? row.domain : ''
}, [rf.state.list])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('corsSettingsDiv') + 'corsSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const map = { request: '目标接口域名', initiator: '发起请求页面', top: '顶层 Frame' }
  $self.value = map[row && row.matchScope] || '目标接口域名'
}, [rf.state.list])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('corsSettingsDiv') + 'corsSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const v = (row && row.excludeDomains && row.excludeDomains.length > 0) ? ('排除: ' + row.excludeDomains.join(', ')) : ''
  $self.value = v
  $self.display = v ? 'visible' : 'none'
}, [rf.state.list])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('corsSettingsDiv') + 'corsSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const v = (row && row.urlFilter && row.urlFilter.trim()) ? ((row.urlFilterIsRegex ? '正则' : 'URL') + ': ' + row.urlFilter) : ''
  $self.value = v
  $self.display = v ? 'visible' : 'none'
}, [rf.state.list])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('corsSettingsDiv') + 'corsSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const v = (row && row.methods && row.methods.length > 0) ? ('方法: ' + row.methods.join('/')) : ''
  $self.value = v
  $self.display = v ? 'visible' : 'none'
}, [rf.state.list])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('corsSettingsDiv') + 'corsSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const v = (row && row.resourceTypes && row.resourceTypes.length > 0) ? ('类型: ' + row.resourceTypes.join('/')) : ''
  $self.value = v
  $self.display = v ? 'visible' : 'none'
}, [rf.state.list])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('corsSettingsDiv') + 'corsSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const v = (row && row.domainType) ? (row.domainType === 'firstParty' ? '第一方' : '第三方') : ''
  $self.value = v
  $self.display = v ? 'visible' : 'none'
}, [rf.state.list])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('corsSettingsDiv') + 'corsSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const has = !!(row && ((row.excludeDomains && row.excludeDomains.length > 0) || (row.urlFilter && row.urlFilter.trim()) || (row.methods && row.methods.length > 0) || (row.resourceTypes && row.resourceTypes.length > 0) || row.domainType))
  $self.value = has ? '' : '—'
  $self.display = has ? 'none' : 'visible'
}, [rf.state.list])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('corsSettingsDiv') + 'corsSettingsDiv'.length)
const rf = $self.query(re).take()
$props({ onClick: () => { const row = $utils.getArrayFieldRow($self, 'ArrayTable'); rf.showAddOrUpdateDialog(row) } })

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('corsSettingsDiv') + 'corsSettingsDiv'.length)
const rf = $self.query(re).take()
$props({ onConfirm: async () => { const row = $utils.getArrayFieldRow($self, 'ArrayTable'); rf.state.list = rf.state.list.filter((i) => i.id !== row.id); await rf.saveCors(rf.state.enabled, rf.state.list); $message.success('规则已删除') } })

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('corsSettingsDiv') + 'corsSettingsDiv'.length)
const rf = $self.query(re).take()
$props({
  onCancel: () => { $self.componentProps.open = false },
  onOk: () => {
    $self.validate().then(async () => {
      const form = $self.value
      const exists = rf.state.list.some((d) => d.domain === form.domain && (d.matchScope || 'request') === form.matchScope && d.id !== form.id)
      if (exists) {
        const dField = $self.query($self.address.entire + '.domain').take()
        if (dField) dField.setFeedback({ type: 'error', messages: ['该域名 + 作用域组合已存在'] })
        return
      }
      const optional = {}
      if (form.excludeDomains && form.excludeDomains.length > 0) optional.excludeDomains = form.excludeDomains
      if (form.urlFilter && form.urlFilter.trim()) {
        optional.urlFilter = form.urlFilter.trim()
        optional.urlFilterIsRegex = form.urlFilterIsRegex
      }
      if (form.methods && form.methods.length > 0) optional.methods = form.methods
      if (form.resourceTypes && form.resourceTypes.length > 0) optional.resourceTypes = form.resourceTypes
      if (form.domainType) optional.domainType = form.domainType
      const list = rf.state.list.slice()
      if (form.id) {
        const merged = { id: form.id, domain: form.domain, matchScope: form.matchScope, ...optional }
        merged.conditionSummary = rf.buildSummary(merged)
        const idx = list.findIndex((i) => i.id === form.id)
        if (idx >= 0) list[idx] = merged
        rf.state.list = list
        await rf.saveCors(rf.state.enabled, list)
        $message.success('规则已更新')
      } else {
        const created = { domain: form.domain, matchScope: form.matchScope, ...optional }
        created.id = 'cors_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7)
        created.conditionSummary = rf.buildSummary(created)
        list.push(created)
        rf.state.list = list
        await rf.saveCors(rf.state.enabled, list)
        $message.success('规则已新增')
      }
      $self.componentProps.open = false
    }).catch((e) => $logger.info('校验失败', e))
  },
})
